from core import *
import json

def render(c):
    t,n=c.t,c.n;body='';nav_start=len(c.sections)
    heads={38:('A clear view of the working day.','Orders, revenue, and the small details that keep a growing shop moving.'),39:('A little movement adds up.','Track the habits that help you feel stronger, steadier, and more like yourself.'),40:('More clarity, less money guesswork.','A sample household budget with a visible balance, spending categories, and recent transactions.'),41:('Keep the next step in sight.','A shared project board for the work that needs doing, the work in motion, and the things worth celebrating.'),42:('Make a little room for the weather.','A fictional local forecast, designed to make the next few days easier to plan.'),43:('A calmer place for your messages.','A sample inbox with searchable messages, useful folders, and a little space to read.'),44:('A soundtrack for the quieter hours.','Original browser-synthesized study loops. Pick a track, press play, and set a comfortable volume.'),45:('A small record of good work.','Projects, shared notes, and the people who make a creative community feel like home.')}
    c.heading,c.intro=heads[t]
    if t==38:
        orders=[]
        for i in range(7):orders.append([f'#{4200+n*8+i}',c.person_at(i),PRODUCTS[(n+i)%len(PRODUCTS)][0],money(24+(n+i)*7),['Packed','Shipped','Processing'][i%3]])
        revenue=sum(24+(n+i)*7 for i in range(7))
        body=c.section('Shop overview',f'<div class="grid gap-4 sm:grid-cols-2">{metric("Today’s revenue",money(revenue),"7 paid orders · before tax")}{metric("Orders processing","2","Next collection · 4:30 PM")}{metric("Returning customers",f"{24+n%12}%","Share of this month’s orders")}{metric("Average order",money(round(revenue/7,2)),"Today’s paid orders")}</div>',id='overview')
        body+=c.section('Recent orders',table(['Order','Customer','Item','Total','Status'],orders,'Today’s order activity'),id='orders')
        body+=c.section('A few things to keep moving',ul(['Print the afternoon collection labels.','Check the linen apron stock before Friday.','Reply to the wholesale inquiry from the neighborhood shop.']),id='notes')
    elif t==39:
        steps=6200+n*137;minutes=28+n%20;water=1.4+(n%6)*.1
        body=c.section('Today’s movement',f'<div class="grid gap-4 sm:grid-cols-2">{metric("Steps",f"{steps:,}","Daily intention · 10,000")}{metric("Active minutes",str(minutes),"Daily intention · 45 minutes")}{metric("Water",f"{water:.1f} L","Personal reminder · 2 liters")}{metric("Sleep",f"{7+n%2} h {n%4*10:02} m","Last night’s recorded rest")}</div>',id='overview')
        week=''
        for i,day in enumerate(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']):
            value=18+(n*7+i*13)%43;percent=min(100,round(value/45*100))
            week+=f'<li class="panel p-4"><div class="flex justify-between gap-3 mb-3"><span class="font-semibold">{day}</span><span class="text-sm muted">{value} / 45 active minutes</span></div><div class="progress-track" role="progressbar" aria-label="{day} active minutes" aria-valuenow="{value}" aria-valuemin="0" aria-valuemax="60"><div class="progress-fill" style="width:{percent}%"></div></div></li>'
        body+=c.section('Your week in motion','<ul class="space-y-3">'+week+'</ul>',id='week')+c.section('The next kind thing',p('A gentle walk and five minutes of mobility can be enough for a recovery day. Choose movement that matches your energy, and leave space for rest.'),id='notes')
    elif t==40:
        spending=[('Groceries',245+n*3),('Transport',78+n),('Home',620+n*4),('Eating out',96+n*2),('Learning',45+n),('Subscriptions',34+n)];spent=sum(x[1] for x in spending);income=3200+n*30;opening=1650+n*20;balance=opening+income-spent
        body=c.section('Your month, clearly',f'<div class="grid gap-4 sm:grid-cols-2">{metric("Available balance",money(balance),"Opening balance + income − spending")}{metric("Income this month",money(income),"Recorded deposits")}{metric("Spending this month",money(spent),"Across six categories")}{metric("Left from this income",money(income-spent),"Before your next savings transfer")}</div>',id='overview')
        cats=''
        for cat,amount in spending:
            percent=round(amount/spent*100)
            cats+=f'<li class="panel p-4"><div class="flex justify-between mb-3 gap-4"><strong>{cat}</strong><span>{money(amount)} · {percent}%</span></div><div class="progress-track"><div class="progress-fill" style="width:{percent}%"></div></div></li>'
        body+=c.section('Where it went','<ul class="grid gap-3 sm:grid-cols-2">'+cats+'</ul>',id='spending')
        body+=c.section('Recent transactions',table(['Date','Description','Category','Amount'],[[f'May {20-i}, 2027',merchant,cat,'−'+money(amount)] for i,(merchant,cat,amount) in enumerate([('Market basket','Groceries',52+n),('Regional rail pass','Transport',28),('Monthly studio desk','Home',120),('Weekend supper','Eating out',38+n),('Course notebook','Learning',19)])],'Sample account activity · USD'),id='transactions')
    elif t==41:
        tasksets=[['Map the onboarding journey','Draft the welcome email','Review mobile navigation','Write the accessibility checklist','Prototype the settings panel','Test the export flow','Publish the research summary','Archive the first sprint','Share the weekly notes'],['Book the community venue','Design the event poster','Confirm the workshop hosts','Prepare the volunteer rota','Order reusable cups','Review the access plan','Publish the program','Send speaker notes','File the venue agreement'],['Measure the workshop space','Sketch the shelving plan','Choose the wood finish','Source the hardware','Assemble the first unit','Sand the shelf edges','Check the wall fixings','Photograph the finished piece','Write the care guide']]
        tasks=tasksets[n%3];board='<div class="grid gap-4 lg:grid-cols-3">'
        for k,title in enumerate(['To Do','Doing','Done']):
            cards=''
            for i,text in enumerate(tasks[k*3:k*3+3]):
                j=k*3+i;next_name=['Doing','Done','To Do'][k]
                cards+=f'<article class="panel p-4 board-task" data-task="{j}"><p class="text-xs accent mb-3">{["Planning","Design","Operations"][i%3]}</p><h4 class="font-semibold">{text}</h4><p class="text-xs muted mt-3">{e(c.person_at(j))} · Jun {12+j}</p><button class="text-sm accent font-bold mt-4 move-task" type="button">Move to {next_name} →</button></article>'
            board+=f'<section class="board-column" data-column="{k}" aria-label="{title}"><h3 class="font-bold mb-4">{title} <span class="column-count muted">3</span></h3><div class="space-y-3 task-stack">{cards}</div></section>'
        body=c.section('The work in view',board+'</div><p id="board-status" class="text-sm muted mt-5" role="status">Nine tasks across three stages.</p>',id='overview')
        body+=c.section('This sprint’s intention',p('Make the first experience clear enough that someone new can get started without a separate explanation. Keep decisions visible and leave a useful note for the next person.'),id='notes')
        c.scripts.append('''const columns=[...document.querySelectorAll('[data-column]')],names=['To Do','Doing','Done'];document.querySelectorAll('.move-task').forEach(button=>button.onclick=()=>{const task=button.closest('.board-task'),from=Number(task.closest('[data-column]').dataset.column),next=(from+1)%3;columns[next].querySelector('.task-stack').append(task);button.textContent='Move to '+names[(next+1)%3]+' →';columns.forEach(column=>column.querySelector('.column-count').textContent=column.querySelectorAll('.board-task').length);document.getElementById('board-status').textContent=task.querySelector('h4').textContent+' moved to '+names[next]+'.';});''')
    elif t==42:
        temp=13+n%11;conditions=['Partly cloudy','Light rain','Mostly sunny','Overcast','Clear skies'];condition=conditions[n%5]
        body=c.section('Right now',f'<div class="panel p-7"><p class="eyebrow accent">Sample forecast · {e(c.city)}</p><div class="flex flex-wrap gap-8 items-center mt-5"><span class="text-6xl" aria-hidden="true">{["⛅","☂","☀","☁","☀"][n%5]}</span><div><p class="text-5xl font-bold">{temp}°C</p><p class="muted mt-2">{condition} · Feels like {temp-1}°C</p></div></div><dl class="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-7"><div><dt class="text-sm muted">Humidity</dt><dd class="font-bold">{52+n%20}%</dd></div><div><dt class="text-sm muted">Wind</dt><dd class="font-bold">SW {8+n%12} km/h</dd></div><div><dt class="text-sm muted">Sunrise</dt><dd class="font-bold">6:12 AM</dd></div><div><dt class="text-sm muted">Sunset</dt><dd class="font-bold">8:34 PM</dd></div></dl></div>',id='overview')
        forecast=''
        for i,day in enumerate(['Monday','Tuesday','Wednesday','Thursday','Friday']):forecast+=f'<article class="panel p-5"><h3 class="font-bold">{day}</h3><p class="text-3xl my-4" aria-hidden="true">{["☀","⛅","☂","☁","☀"][(n+i)%5]}</p><p class="font-semibold">{temp+i%3}° / {temp-6+i%2}°C</p><p class="text-sm muted mt-2">{conditions[(n+i)%5]}</p><p class="text-xs muted mt-3">Rain chance: {(n+i)%5*20}%</p></article>'
        body+=c.section('The five-day outlook',f'<div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{forecast}</div>',id='forecast')+c.section('A good day for a short walk',p('Take a light layer for the shaded paths and a small umbrella if you will be out after lunch. This is an illustrative forecast, not live weather information.'),id='notes')
    elif t==43:
        messages=[]
        for i,(title,cat,text) in enumerate(pick(ARTICLES,n,7)):messages.append({'sender':c.person_at(i),'subject':title,'body':f'Hi {c.person.split()[0]},\n\n{text} I have put together the first notes and would value your thoughts before our next conversation.\n\nCould you review the main points and bring one suggestion to Thursday’s session? There is no rush today.\n\nThanks,\n{c.person_at(i).split()[0]}','folder':'Saved' if i%3==0 else 'Inbox'})
        buttons=''.join(f'<button type="button" data-message="{i}" class="block w-full text-left border-b divider p-4"><span class="text-xs accent">{e(m["sender"])}</span><strong class="block mt-1 text-sm">{e(m["subject"])}</strong><span class="text-xs muted">{m["folder"]} · {9+i}:15 AM</span></button>' for i,m in enumerate(messages))
        body=c.section('Your messages',f'<div class="panel p-5"><div class="flex flex-wrap gap-3 mb-4"><button class="btn btn-secondary" id="folder-inbox" type="button" aria-pressed="true">Inbox</button><button class="btn btn-secondary" id="folder-saved" type="button" aria-pressed="false">Saved</button><button class="btn btn-secondary" id="folder-all" type="button" aria-pressed="false">All messages</button></div><label for="message-search" class="font-semibold text-sm">Search sender or subject</label><input id="message-search" type="search" class="field w-full rounded-lg p-3 mt-2" autocomplete="off"><div class="grid md:grid-cols-2 gap-5 mt-5"><div id="message-list" class="panel overflow-hidden">{buttons}<p id="no-messages" class="p-5 muted" hidden>No matching messages.</p></div><article class="panel p-5"><p id="message-sender" class="text-sm accent"></p><h3 id="message-subject" class="text-xl font-bold mt-2"></h3><p id="message-body" class="leading-relaxed mt-5 whitespace-pre-line"></p></article></div></div>',id='overview')
        c.scripts.append('''const messages='''+json.dumps(messages)+''',buttons=[...document.querySelectorAll('[data-message]')],search=document.getElementById('message-search');let folder='Inbox';function openMessage(i){const m=messages[i];document.getElementById('message-sender').textContent=m.sender;document.getElementById('message-subject').textContent=m.subject;document.getElementById('message-body').textContent=m.body;buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(j===i)));}function filterMessages(){let visible=[];buttons.forEach((button,i)=>{const m=messages[i],query=search.value.trim().toLowerCase(),show=(folder==='All'||m.folder===folder)&&(m.sender+' '+m.subject).toLowerCase().includes(query);button.hidden=!show;if(show)visible.push(i);});document.getElementById('no-messages').hidden=visible.length>0;if(visible.length)openMessage(visible[0]);else{document.getElementById('message-sender').textContent='';document.getElementById('message-subject').textContent='Nothing to read here yet';document.getElementById('message-body').textContent='Try another folder or a shorter search.';}}buttons.forEach((button,i)=>button.onclick=()=>openMessage(i));['inbox','saved','all'].forEach(key=>document.getElementById('folder-'+key).onclick=()=>{folder=key==='all'?'All':key==='saved'?'Saved':'Inbox';['inbox','saved','all'].forEach(k=>document.getElementById('folder-'+k).setAttribute('aria-pressed',String(k===key)));filterMessages();});search.oninput=filterMessages;filterMessages();''')
    elif t==44:
        tracks=pick(TRACKS,n,6)
        rows=''.join(f'<li><button type="button" class="track-button flex w-full gap-3 text-left p-4 border-b divider" data-track="{i}" aria-pressed="{str(i==0).lower()}"><span class="muted text-xs w-6">{i+1:02}</span><span class="flex-1"><strong class="block">{e(title)}</strong><span class="text-sm muted">{artist}</span></span><span class="text-sm muted">{length//60}:{length%60:02}</span></button></li>' for i,(title,artist,length) in enumerate(tracks))
        body=c.section('At the listening desk',f'<div class="grid gap-6 lg:grid-cols-2"><div class="panel overflow-hidden">{c.art("record", "An original record sleeve for a quiet study playlist", "w-full h-64")}<div class="p-6"><p class="eyebrow accent">Now playing</p><h3 id="track-title" class="text-2xl font-bold mt-3">{tracks[0][0]}</h3><p id="track-artist" class="muted mt-1">{tracks[0][1]}</p><div class="flex flex-wrap gap-3 mt-6">{btn("Previous",attrs="id=previous-track",secondary=True)}{btn("Play",attrs="id=play-track aria-pressed=false")}{btn("Next",attrs="id=next-track",secondary=True)}</div><div class="progress-track mt-5"><div id="track-progress" class="progress-fill" style="width:0%"></div></div><p id="track-time" class="text-sm muted mt-2" role="status">0:00</p><label for="volume" class="block text-sm mt-5">Volume</label><input id="volume" type="range" min="0" max="100" value="25" class="w-full mt-2"></div></div><div class="panel p-3"><h3 class="font-bold px-4 py-3">The quiet-hours playlist</h3><ol>{rows}</ol></div></div>',id='overview')
        c.scripts.append('''const tracks='''+json.dumps(tracks)+''';let current=0,playing=false,elapsed=0,audio,voice,gain;const play=document.getElementById('play-track');function stopSound(){if(voice){voice.stop();voice.disconnect();voice=null;}}function startSound(){if(!audio)audio=new AudioContext();audio.resume();gain=audio.createGain();gain.gain.value=Number(document.getElementById('volume').value)/100*.08;gain.connect(audio.destination);voice=audio.createOscillator();voice.type='sine';voice.frequency.value=[220,261.63,293.66,329.63,349.23,392][current];voice.connect(gain);voice.start();}function show(){const track=tracks[current];document.getElementById('track-title').textContent=track[0];document.getElementById('track-artist').textContent=track[1];document.querySelectorAll('[data-track]').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===current)));play.textContent=playing?'Pause':'Play';play.setAttribute('aria-pressed',String(playing));document.getElementById('track-time').textContent=Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0')+' / '+Math.floor(track[2]/60)+':'+String(track[2]%60).padStart(2,'0');document.getElementById('track-progress').style.width=(elapsed/track[2]*100)+'%';}function selectTrack(i){stopSound();current=(i+tracks.length)%tracks.length;elapsed=0;if(playing)startSound();show();}play.onclick=()=>{playing=!playing;if(playing)startSound();else stopSound();show();};document.getElementById('previous-track').onclick=()=>selectTrack(current-1);document.getElementById('next-track').onclick=()=>selectTrack(current+1);document.querySelectorAll('[data-track]').forEach(button=>button.onclick=()=>selectTrack(Number(button.dataset.track)));document.getElementById('volume').oninput=event=>{if(gain)gain.gain.value=event.target.value/100*.08;};setInterval(()=>{if(playing){elapsed++;if(voice)voice.frequency.setTargetAtTime([220,261.63,293.66,329.63,349.23,392][(current+Math.floor(elapsed/4))%6],audio.currentTime,.3);if(elapsed>=tracks[current][2]){playing=false;stopSound();}show();}},1000);show();''')
    elif t==45:
        body=c.section('Meet the maker',f'<div class="panel p-6"><div class="flex flex-wrap items-center gap-5">{c.image("person"+str(n%6+1),"Portrait representing "+c.person,"w-24 h-24 rounded-full object-cover")}<div class="flex-1"><h3 class="text-2xl font-bold">{e(c.person)}</h3><p class="muted mt-2">Independent designer · {e(c.city)}</p><p class="text-sm mt-3">Making useful interfaces and leaving good notes for the next person.</p></div>{btn("Follow",attrs="id=follow-profile aria-pressed=false")}</div><div class="grid grid-cols-3 gap-4 mt-7 border-t divider pt-5"><div><strong class="text-2xl">{12+n}</strong><p class="text-sm muted">Projects</p></div><div><strong id="follower-count" class="text-2xl">{320+n*17}</strong><p class="text-sm muted">Followers</p></div><div><strong class="text-2xl">{48+n}</strong><p class="text-sm muted">Field notes</p></div></div><p id="follow-status" class="text-sm muted mt-4" role="status">Follow to mark this profile in your current visit.</p></div>',id='overview')
        activity=''
        for i,(title,cat,text) in enumerate(pick(ARTICLES,n,4)):activity+=f'<li class="panel p-5"><p class="text-xs accent">June {20-i*2}, 2027 · {cat}</p><h3 class="font-bold mt-2">{title}</h3>{p(text,"text-sm mt-2")}</li>'
        body+=c.section('Notes from the workbench','<ol class="space-y-4">'+activity+'</ol>',id='activity')
        c.scripts.append('''const follow=document.getElementById('follow-profile'),followers=document.getElementById('follower-count'),base=Number(followers.textContent);follow.onclick=()=>{const active=follow.getAttribute('aria-pressed')!=='true';follow.setAttribute('aria-pressed',String(active));follow.textContent=active?'Following':'Follow';followers.textContent=base+(active?1:0);document.getElementById('follow-status').textContent=active?'Following for this visit.':'You are no longer following this profile.';};''')
    links=''.join(f'<a href="#{ident}" {"aria-current=page" if i==0 else ""}>{e(title)}</a>' for i,(ident,title) in enumerate(c.sections[nav_start:]))
    sidebar=f'<aside class="panel p-4 self-start md:sticky md:top-6"><p class="eyebrow accent px-3 py-3">Your workspace</p><nav aria-label="Workspace sections" class="app-nav">{links}</nav><div class="border-t divider mt-6 pt-5 px-3"><p class="text-sm font-bold">{e(c.person)}</p><p class="text-xs muted mt-1">Community workspace</p></div></aside>'
    return f'<div class="grid gap-6 md:grid-cols-4">{sidebar}<div class="md:col-span-3 min-w-0">{body}</div></div>'
